50	/// A preprocessed `CompileCommand`.
51	pub struct CompileConfig {
52	    /// Static warnings to emit after compilation.
53	    pub warnings: Vec<HintedString>,
54	    /// Whether we are watching.
55	    pub watching: bool,
56	    /// Path to input Typst file or stdin.
57	    pub input: Input,
58	    /// Path to output file (PDF, PNG, SVG, or HTML).
59	    pub output: Output,
60	    /// The format of the output file.
61	    pub output_format: OutputFormat,
62	    /// Whether to make the serialized document pretty.
63	    pub pretty: bool,
64	    /// Which pages to export.
65	    pub pages: Option<PageRanges>,
66	    /// The document's creation date formatted as a UNIX timestamp, with UTC suffix.
67	    pub creation_timestamp: Option<DateTime<Utc>>,
68	    /// The format to emit diagnostics in.
69	    pub diagnostic_format: DiagnosticFormat,
70	    /// Opens the output file with the default viewer or a specific program after
71	    /// compilation.
72	    pub open: Option<Option<String>>,
73	    /// A list of standards the PDF should conform to.
74	    pub pdf_standards: PdfStandards,
75	    /// Whether to write PDF (accessibility) tags.
76	    pub tagged: bool,
77	    /// A destination to write a list of dependencies to.
78	    pub deps: Option<Output>,
79	    /// The format to use for dependencies.
80	    pub deps_format: DepsFormat,
81	    /// The PPI (pixels per inch) to use for PNG export.
82	    pub ppi: f64,
83	    /// The export cache for images, used for caching output files in `typst
84	    /// watch` sessions with images.
85	    pub export_cache: ExportCache,
86	    /// Server for `typst watch` to HTML.
87	    #[cfg(feature = "http-server")]
88	    pub server: Option<HttpServer>,
89	}
90	
91	impl CompileConfig {
92	    /// Preprocess a `CompileCommand`, producing a compilation config.
93	    pub fn new(command: &CompileCommand) -> HintedStrResult<Self> {
94	        Self::new_impl(&command.args, None)
95	    }
96	
97	    /// Preprocess a `WatchCommand`, producing a compilation config.
98	    pub fn watching(command: &WatchCommand) -> HintedStrResult<Self> {
99	        Self::new_impl(&command.args, Some(command))
100	    }
101	
102	    /// The shared implementation of [`CompileConfig::new`] and
103	    /// [`CompileConfig::watching`].
104	    fn new_impl(
105	        args: &CompileArgs,
106	        watch: Option<&WatchCommand>,
107	    ) -> HintedStrResult<Self> {
108	        let mut warnings = Vec::new();
109	        let input = args.input.clone();
110	
111	        let output_format = if let Some(specified) = args.format {
112	            specified
113	        } else if let Some(Output::Path(output)) = &args.output {
114	            match output.extension() {
115	                Some(ext) if ext.eq_ignore_ascii_case("pdf") => OutputFormat::Pdf,
116	                Some(ext) if ext.eq_ignore_ascii_case("png") => OutputFormat::Png,
117	                Some(ext) if ext.eq_ignore_ascii_case("svg") => OutputFormat::Svg,
118	                Some(ext) if ext.eq_ignore_ascii_case("html") => OutputFormat::Html,
119	                _ => bail!(
120	                    "could not infer output format for path {}.\n\
121	                     consider providing the format manually with `--format/-f`",
122	                    output.display(),
123	                ),
124	            }
125	        } else {
126	            OutputFormat::Pdf
127	        };
128	
129	        let output = args.output.clone().unwrap_or_else(|| {
130	            let Input::Path(path) = &input else {
131	                panic!("output must be specified when input is from stdin, as guarded by the CLI");
132	            };
133	            Output::Path(path.with_extension(
134	                match output_format {
135	                    OutputFormat::Pdf => "pdf",
136	                    OutputFormat::Png => "png",
137	                    OutputFormat::Svg => "svg",
138	                    OutputFormat::Html => "html",
139	                    OutputFormat::Bundle => "",
140	                },
141	            ))
142	        });
143	
144	        let pages = args.pages.as_ref().map(|export_ranges| {
145	            PageRanges::new(export_ranges.iter().map(|r| r.0.clone()).collect())
146	        });
147	
148	        let tagged = !args.no_pdf_tags && pages.is_none();
149	        if output_format == OutputFormat::Pdf && pages.is_some() && !args.no_pdf_tags {
150	            warnings.push(
151	                HintedString::from("using --pages implies --no-pdf-tags").with_hints([
152	                    "the resulting PDF will be inaccessible".into(),
153	                    "add --no-pdf-tags to silence this warning".into(),
154	                ]),
155	            );
156	        }
157	
158	        if !tagged {
159	            const ACCESSIBLE: &[(PdfStandard, &str)] = &[
160	                (PdfStandard::A_1a, "PDF/A-1a"),
161	                (PdfStandard::A_2a, "PDF/A-2a"),
162	                (PdfStandard::A_3a, "PDF/A-3a"),
163	                (PdfStandard::UA_1, "PDF/UA-1"),
164	            ];
165	
166	            for (standard, name) in ACCESSIBLE {
167	                if args.pdf_standard.contains(standard) {
168	                    if args.no_pdf_tags {
169	                        bail!("cannot disable PDF tags when exporting a {name} document");
170	                    } else {
171	                        bail!(
172	                            "cannot disable PDF tags when exporting a {name} document";
173	                            hint: "using --pages implies --no-pdf-tags";
174	                        );
175	                    }
176	                }
177	            }
178	        }
179	
180	        let pdf_standards = PdfStandards::new(
181	            &args.pdf_standard.iter().copied().map(Into::into).collect::<Vec<_>>(),
182	        )?;
183	
184	        #[cfg(feature = "http-server")]
185	        let server = if let Some(command) = watch
186	            && !command.server.no_serve
187	            && matches!(output_format, OutputFormat::Html | OutputFormat::Bundle)
188	        {
189	            Some(HttpServer::new(
190	                &eco_format!("{input}"),
191	                command.server.port,
192	                !command.server.no_reload,
193	            )?)
194	        } else {
195	            None
196	        };
197	
198	        let mut deps = args.deps.clone();
199	        let mut deps_format = args.deps_format;
200	
201	        if let Some(path) = &args.make_deps
202	            && deps.is_none()
203	        {
204	            deps = Some(Output::Path(path.clone()));
205	            deps_format = DepsFormat::Make;
206	            warnings.push(
207	                "--make-deps is deprecated, use --deps and --deps-format instead".into(),
208	            );
209	        }
210	
211	        match (&output, &deps, watch) {
212	            (Output::Stdout, _, Some(_)) => {
213	                bail!("cannot write document to stdout in watch mode");
214	            }
215	            (_, Some(Output::Stdout), Some(_)) => {
216	                bail!("cannot write dependencies to stdout in watch mode")
217	            }
218	            (Output::Stdout, Some(Output::Stdout), _) => {
219	                bail!("cannot write both output and dependencies to stdout")
220	            }
221	            _ => {}
222	        }
223	
224	        Ok(Self {
225	            warnings,
226	            watching: watch.is_some(),
227	            input,
228	            output,
229	            output_format,
230	            pretty: args.pretty,
231	            pages,
232	            pdf_standards,
233	            tagged,
234	            creation_timestamp: args
235	                .world
236	                .creation_timestamp
237	                .map(|time| {
238	                    chrono::DateTime::from_timestamp(time, 0)
239	                        .ok_or("creation timestamp is out of range")
240	                })
241	                .transpose()?,
242	            ppi: args.ppi,
243	            diagnostic_format: args.process.diagnostic_format,
244	            open: args.open.clone(),
245	            export_cache: ExportCache::new(),
246	            deps,
247	            deps_format,
248	            #[cfg(feature = "http-server")]
249	            server,
250	        })
251	    }
252	}
253	
254	/// Compile a single time.
255	///
256	/// Returns whether it compiled without errors.
257	#[typst_macros::time(name = "compile once")]
258	pub fn compile_once(
259	    world: &mut SystemWorld,
260	    config: &mut CompileConfig,
261	) -> HintedStrResult<()> {
262	    let start = std::time::Instant::now();
263	    if config.watching {
264	        Status::Compiling.print(config).unwrap();
265	    }
266	
267	    let Warned { output, mut warnings } = compile_and_export(world, config);
268	
269	    // Add static warnings (for deprecated CLI flags and such).
270	    for warning in &config.warnings {
271	        warnings.push(
272	            SourceDiagnostic::warning(Span::detached(), warning.message())
273	                .with_hints(warning.hints().iter().map(Into::into)),
274	        );
275	    }
276	
277	    match &output {
278	        // Print success message and possibly warnings.
279	        Ok(_) => {
280	            let duration = start.elapsed();
281	            if config.watching {
282	                if warnings.is_empty() {
283	                    Status::Success(duration).print(config).unwrap();
284	                } else {
285	                    Status::PartialSuccess(duration).print(config).unwrap();
286	                }
287	            }
288	
289	            print_diagnostics(world, &[], &warnings, config.diagnostic_format)
290	                .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
291	
292	            open_output(config)?;
293	        }
294	
295	        // Print failure message and diagnostics.
296	        Err(errors) => {
297	            set_failed();
298	
299	            if config.watching {
300	                Status::Error.print(config).unwrap();
301	            }
302	
303	            print_diagnostics(world, errors, &warnings, config.diagnostic_format)
304	                .map_err(|err| eco_format!("failed to print diagnostics ({err})"))?;
305	        }
306	    }
307	
308	    if let Some(dest) = &config.deps {
309	        write_deps(world, dest, config.deps_format, output.as_deref().ok())
310	            .map_err(|err| eco_format!("failed to create dependency file ({err})"))?;
311	    }
312	
313	    Ok(())
314	}
315	
316	/// Compile and then export the document.
317	fn compile_and_export(
318	    world: &mut SystemWorld,
319	    config: &mut CompileConfig,
320	) -> Warned<SourceResult<Vec<Output>>> {
321	    match config.output_format {
322	        OutputFormat::Pdf | OutputFormat::Png | OutputFormat::Svg => {
323	            let Warned { output, warnings } = typst::compile::<PagedDocument>(world);
324	            let result = output.and_then(|document| export_paged(&document, config));
325	            Warned { output: result, warnings }
326	        }
327	        OutputFormat::Html => {
328	            let Warned { output, warnings } = typst::compile::<HtmlDocument>(world);
329	            let result = output.and_then(|document| export_html(&document, config));
330	            Warned {
331	                output: result.map(|()| vec![config.output.clone()]),
332	                warnings,
333	            }
334	        }
335	        OutputFormat::Bundle => {
336	            let Warned { output, warnings } = typst::compile::<Bundle>(world);
337	            let result = output.and_then(|bundle| export_bundle(bundle, config));
338	            Warned { output: result, warnings }
339	        }
340	    }
341	}
342	
343	/// Export to HTML.
344	fn export_html(document: &HtmlDocument, config: &CompileConfig) -> SourceResult<()> {
345	    let options = HtmlOptions { pretty: config.pretty };
346	    let html = typst_html::html(document, &options)?;
347	    let result = config.output.write(html.as_bytes());
348	
349	    #[cfg(feature = "http-server")]
350	    if let Some(server) = &config.server {
351	        server.set_html(html);
352	    }
353	
354	    result
355	        .map_err(|err| eco_format!("failed to write HTML file ({err})"))
356	        .at(Span::detached())
357	}
358	
359	/// Export to a paged target format.
360	fn export_paged(
361	    document: &PagedDocument,
362	    config: &CompileConfig,
363	) -> SourceResult<Vec<Output>> {
364	    match config.output_format {
365	        OutputFormat::Pdf => {
366	            export_pdf(document, config).map(|()| vec![config.output.clone()])
367	        }
368	        OutputFormat::Png => {
369	            export_image(document, config, ImageExportFormat::Png).at(Span::detached())
370	        }
371	        OutputFormat::Svg => {
372	            export_image(document, config, ImageExportFormat::Svg).at(Span::detached())
373	        }
374	        OutputFormat::Html | OutputFormat::Bundle => unreachable!(),
375	    }
376	}
377	
378	/// Export to a PDF.
379	fn export_pdf(document: &PagedDocument, config: &CompileConfig) -> SourceResult<()> {
380	    let options = pdf_options(config);
381	    let buffer = typst_pdf::pdf(document, &options)?;
382	    config
383	        .output
384	        .write(&buffer)
385	        .map_err(|err| eco_format!("failed to write PDF file ({err})"))
386	        .at(Span::detached())?;
387	    Ok(())
388	}
389	
390	/// Export to a bundle, a collection of files in a directory.
391	fn export_bundle(bundle: Bundle, config: &CompileConfig) -> SourceResult<Vec<Output>> {
392	    let options = BundleOptions {
393	        html: html_options(config),
394	        pdf: pdf_options(config),
395	        png: png_options(config),
396	        svg: svg_options(config),
397	    };
398	
399	    let fs = typst_bundle::export(&bundle, &options)?;
400	    let root = match &config.output {
401	        Output::Path(path) => path,
402	        Output::Stdout => {
403	            bail!(Span::detached(), "cannot write bundle to standard output")
404	        }
405	    };
406	
407	    let outputs = write_virtual_fs(root, &fs).at(Span::detached())?;
408	
409	    #[cfg(feature = "http-server")]
410	    if let Some(server) = &config.server {
411	        server.set_bundle(bundle, fs);
412	    }
413	
414	    Ok(outputs)
415	}
416	
417	/// Writes a bundle's files to disk.
418	fn write_virtual_fs(root: &Path, fs: &VirtualFs) -> StrResult<Vec<Output>> {
419	    std::fs::create_dir_all(root)
420	        .map_err(|err| eco_format!("failed to create output directory ({err})"))?;
421	
422	    fs.par_iter()
423	        .map(|(path, data)| {
424	            let realized = path
425	                .realize(root)
426	                .map_err(|err| eco_format!("failed to realize path ({err})"))?;
427	
428	            if let Some(parent) = realized.parent() {
429	                std::fs::create_dir_all(parent)
430	                    .map_err(|err| eco_format!("failed to create directory ({err})"))?;
431	            }
432	
433	            std::fs::write(&realized, data)
434	                .map_err(|err| eco_format!("failed to write file ({err})"))?;
435	            Ok(Output::Path(realized))
436	        })
437	        .collect()
438	}
439	
440	/// Convert [`chrono::DateTime`] to [`Datetime`]
441	fn convert_datetime<Tz: chrono::TimeZone>(
442	    date_time: chrono::DateTime<Tz>,
443	) -> Option<Datetime> {
444	    Datetime::from_ymd_hms(
445	        date_time.year(),
446	        date_time.month().try_into().ok()?,
447	        date_time.day().try_into().ok()?,
448	        date_time.hour().try_into().ok()?,
449	        date_time.minute().try_into().ok()?,
450	        date_time.second().try_into().ok()?,
451	    )
452	}
453	
454	/// An image format to export in.
455	#[derive(Copy, Clone)]
456	enum ImageExportFormat {
457	    Png,
458	    Svg,
459	}
460	
461	/// Export to one or multiple images.
462	fn export_image(
463	    document: &PagedDocument,
464	    config: &CompileConfig,
465	    fmt: ImageExportFormat,
466	) -> StrResult<Vec<Output>> {
467	    // Determine whether we have indexable templates in output
468	    let can_handle_multiple = match config.output {
469	        Output::Stdout => false,
470	        Output::Path(ref output) => {
471	            output_template::has_indexable_template(output.to_str().unwrap_or_default())
472	        }
473	    };
474	
475	    let exported_pages = document
476	        .pages()
477	        .iter()
478	        .enumerate()
479	        .filter(|(i, _)| {
480	            config.pages.as_ref().is_none_or(|exported_page_ranges| {
481	                exported_page_ranges.includes_page_index(*i)
482	            })
483	        })
484	        .collect::<Vec<_>>();
485	
486	    if !can_handle_multiple && exported_pages.len() > 1 {
487	        let err = match config.output {
488	            Output::Stdout => "to stdout",
489	            Output::Path(_) => {
490	                "without a page number template ({p}, {0p}) in the output path"
491	            }
492	        };
493	        bail!("cannot export multiple images {err}");
494	    }
495	
496	    // The results are collected in a `Vec<()>` which does not allocate.
497	    exported_pages
498	        .par_iter()
499	        .map(|(i, page)| {
500	            // Use output with converted path.
501	            let output = match &config.output {
502	                Output::Path(path) => {
503	                    let storage;
504	                    let path = if can_handle_multiple {
505	                        storage = output_template::format(
506	                            path.to_str().unwrap_or_default(),
507	                            i + 1,
508	                            document.pages().len(),
509	                        );
510	                        Path::new(&storage)
511	                    } else {
512	                        path
513	                    };
514	
515	                    // If we are not watching, don't use the cache.
516	                    // If the frame is in the cache, skip it.
517	                    // If the file does not exist, always create it.
518	                    if config.watching
519	                        && config.export_cache.is_cached(*i, page)
520	                        && path.exists()
521	                    {
522	                        return Ok(Output::Path(path.to_path_buf()));
523	                    }
524	
525	                    Output::Path(path.to_owned())
526	                }
527	                Output::Stdout => Output::Stdout,
528	            };
529	
530	            export_image_page(config, page, &output, fmt)?;
531	            Ok(output)
532	        })
533	        .collect::<StrResult<Vec<Output>>>()
534	}
535	
536	mod output_template {
537	    const INDEXABLE: [&str; 3] = ["{p}", "{0p}", "{n}"];
538	
539	    pub fn has_indexable_template(output: &str) -> bool {
540	        INDEXABLE.iter().any(|template| output.contains(template))
541	    }
542	
543	    pub fn format(output: &str, this_page: usize, total_pages: usize) -> String {
544	        // Find the base 10 width of number `i`
545	        fn width(i: usize) -> usize {
546	            1 + i.checked_ilog10().unwrap_or(0) as usize
547	        }
548	
549	        let other_templates = ["{t}"];
550	        INDEXABLE.iter().chain(other_templates.iter()).fold(
551	            output.to_string(),
552	            |out, template| {
553	                let replacement = match *template {
554	                    "{p}" => format!("{this_page}"),
555	                    "{0p}" | "{n}" => format!("{:01$}", this_page, width(total_pages)),
556	                    "{t}" => format!("{total_pages}"),
557	                    _ => unreachable!("unhandled template placeholder {template}"),
558	                };
559	                out.replace(template, replacement.as_str())
560	            },
561	        )
562	    }
563	}
564	
565	/// Export single image.
566	fn export_image_page(
567	    config: &CompileConfig,
568	    page: &Page,
569	    output: &Output,
570	    fmt: ImageExportFormat,
571	) -> StrResult<()> {
572	    match fmt {
573	        ImageExportFormat::Png => {
574	            let options = png_options(config);
575	            let pixmap = typst_render::render(page, &options);
576	            let buf = pixmap
577	                .encode_png()
578	                .map_err(|err| eco_format!("failed to encode PNG file ({err})"))?;
579	            output
580	                .write(&buf)
581	                .map_err(|err| eco_format!("failed to write PNG file ({err})"))?;
582	        }
583	        ImageExportFormat::Svg => {
584	            let options = svg_options(config);
585	            let svg = typst_svg::svg(page, &options);
586	            output
587	                .write(svg.as_bytes())
588	                .map_err(|err| eco_format!("failed to write SVG file ({err})"))?;
589	        }
590	    }
591	    Ok(())
592	}
593	
594	/// Creates options for HTML export.
595	fn html_options(config: &CompileConfig) -> HtmlOptions {
596	    HtmlOptions { pretty: config.pretty }
597	}
598	
599	/// Creates options for PDF export.
600	fn pdf_options(config: &CompileConfig) -> PdfOptions {
601	    // If the timestamp is provided through the CLI, use UTC suffix,
602	    // else, use the current local time and timezone.
603	    let timestamp = match config.creation_timestamp {
604	        Some(timestamp) => convert_datetime(timestamp).map(Timestamp::new_utc),
605	        None => {
606	            let local_datetime = chrono::Local::now();
607	            convert_datetime(local_datetime).and_then(|datetime| {
608	                Timestamp::new_local(
609	                    datetime,
610	                    local_datetime.offset().local_minus_utc() / 60,
611	                )
612	            })
613	        }
614	    };
615	
616	    PdfOptions {
617	        ident: Smart::Auto,
618	        creator: Smart::Auto,
619	        timestamp,
620	        page_ranges: config.pages.clone(),
621	        standards: config.pdf_standards.clone(),
622	        tagged: config.tagged,
623	        pretty: config.pretty,
624	    }
625	}
626	
627	/// Creates options for SVG export.
628	fn svg_options(config: &CompileConfig) -> SvgOptions {
629	    SvgOptions { render_bleed: false, pretty: config.pretty }
630	}
631	
632	/// Creates options for PNG export.
633	fn png_options(config: &CompileConfig) -> RenderOptions {
634	    RenderOptions {
635	        pixel_per_pt: Scalar::new(config.ppi / 72.0),
636	        render_bleed: false,
637	    }
638	}
639	
640	/// Caches exported files so that we can avoid re-exporting them if they haven't
641	/// changed.
642	///
643	/// This is done by having a list of size `files.len()` that contains the hashes
644	/// of the last rendered frame in each file. If a new frame is inserted, this
645	/// will invalidate the rest of the cache, this is deliberate as to decrease the
646	/// complexity and memory usage of such a cache.
647	pub struct ExportCache {
648	    /// The hashes of last compilation's frames.
649	    pub cache: RwLock<Vec<u128>>,
650	}
651	
652	impl ExportCache {
653	    /// Creates a new export cache.
654	    pub fn new() -> Self {
655	        Self { cache: RwLock::new(Vec::with_capacity(32)) }
656	    }
657	
658	    /// Returns true if the entry is cached and appends the new hash to the
659	    /// cache (for the next compilation).
660	    pub fn is_cached(&self, i: usize, page: &Page) -> bool {
661	        let hash = typst::utils::hash128(page);
662	
663	        let mut cache = self.cache.upgradable_read();
664	        if i >= cache.len() {
665	            cache.with_upgraded(|cache| cache.push(hash));
666	            return false;
667	        }
668	
669	        cache.with_upgraded(|cache| std::mem::replace(&mut cache[i], hash) == hash)
670	    }
671	}
672	
673	/// Opens the output if desired.
674	fn open_output(config: &mut CompileConfig) -> StrResult<()> {
675	    let Some(viewer) = config.open.take() else { return Ok(()) };
676	
677	    #[cfg(feature = "http-server")]
678	    if let Some(server) = &config.server {
679	        let url = format!("http://{}", server.addr());
680	        return open_path(OsStr::new(&url), viewer.as_deref());
681	    }
682	
683	    // Can't open stdout.
684	    let Output::Path(path) = &config.output else { return Ok(()) };
685	
686	    // Some resource openers require the path to be canonicalized.
687	    let path = path
688	        .canonicalize()
689	        .map_err(|err| eco_format!("failed to canonicalize path ({err})"))?;
690	
691	    open_path(path.as_os_str(), viewer.as_deref())
692	}
693	
694	/// Opens the given file using:
695	///
696	/// - The default file viewer if `app` is `None`.
697	/// - The given viewer provided by `app` if it is `Some`.
698	fn open_path(path: &OsStr, viewer: Option<&str>) -> StrResult<()> {
699	    if let Some(viewer) = viewer {
700	        open::with_detached(path, viewer)
701	            .map_err(|err| eco_format!("failed to open file with {viewer} ({err})"))
702	    } else {
703	        open::that_detached(path).map_err(|err| {
704	            let openers = open::commands(path)
705	                .iter()
706	                .map(|command| command.get_program().to_string_lossy())
707	                .collect::<Vec<_>>()
708	                .join(", ");
709	            eco_format!(
710	                "failed to open file with any of these resource openers: {openers} \
711	                 ({err})",
712	            )
713	        })
714	    }
715	}
